def _ends_with_terminator(word: str) -> bool:
    if not word:
        return False
    # Strip trailing closing quotes/brackets.
    i = len(word) - 1
    while i >= 0 and word[i] in _CLOSERS:
        i -= 1
    if i < 0:
        return False
    if word[i] not in _TERMINATORS:
        return False
    # Must be a terminator run (all remaining leading chars are terminators).
    j = i
    while j >= 0 and word[j] in _TERMINATORS:
        j -= 1
    return True


def _starts_with_upper(word: str) -> bool:
